// Reads the aggregated Mongo docs and emits the JSON contract that the
// Safety Explorer site (lib/api.ts -> ApiResponse) consumes.
var input = $input.all()[0];
var raw = (input && input.json && Array.isArray(input.json.data)) ? input.json.data : [];
var docs = raw.filter(function (d) { return d && Object.keys(d).length > 0; });

function str(v) { return (v === null || v === undefined) ? "" : String(v); }

var items = docs.map(function (d, i) {
  var sourceName = str(d.source_name || d.source_id) || "Unknown Source";
  var id = str(d.content_hash || d._id || d.url) || String(i + 1);
  var tags = Array.isArray(d.tags) ? d.tags : (d.tags ? [d.tags] : []);
  return {
    id: id,
    title: str(d.title) || "(untitled)",
    summary: str(d.summary),
    content: str(d.content),
    url: str(d.url),
    publishedAt: d.published_at || null,
    fetchedAt: d.fetched_at || null,
    category: str(d.category) || "Aviation News",
    tags: tags,
    sourceName: sourceName,
    sourceId: str(d.source_id)
  };
});

// ---- aggregate stats -------------------------------------------------------
var sourceCounts = {};
var categoryCounts = {};
var lastItemDate = null;
var adCount = 0;

items.forEach(function (it) {
  if (it.sourceName) sourceCounts[it.sourceName] = (sourceCounts[it.sourceName] || 0) + 1;
  if (it.category) categoryCounts[it.category] = (categoryCounts[it.category] || 0) + 1;
  if (it.category === "Airworthiness Directive" || (it.tags || []).indexOf("AD") >= 0) adCount++;
  var d = it.publishedAt || it.fetchedAt;
  if (d && (!lastItemDate || String(d) > String(lastItemDate))) lastItemDate = d;
});

function toSortedArray(obj) {
  return Object.keys(obj)
    .map(function (name) { return { name: name, count: obj[name] }; })
    .sort(function (a, b) { return b.count - a.count; });
}

var topSources = toSortedArray(sourceCounts);
var categoryBreakdown = toSortedArray(categoryCounts);

var response = {
  ok: true,
  generatedAt: new Date().toISOString(),
  lastItemDate: lastItemDate,
  stats: {
    total: items.length,
    sources: Object.keys(sourceCounts).length,
    adCount: adCount,
    categories: Object.keys(categoryCounts).length
  },
  topSources: topSources,
  categoryBreakdown: categoryBreakdown,
  items: items
};

return [{ json: response }];
